insert into public.questions (id, subject, grade, category, difficulty, body, answer, distractors, explanation, image_url) values
  ('soc_1_b3_001', '社会', 1, '北アメリカ州', 1, '北アメリカ大陸の西部を南北に連なる、高くけわしい山脈を何というか。', 'ロッキー山脈', array['アパラチア山脈', 'アンデス山脈', 'ヒマラヤ山脈'], '北アメリカ大陸は西部に高くけわしいロッキー山脈、東部に低くなだらかなアパラチア山脈が連なる。アンデス山脈は南アメリカ大陸の山脈。', null),
  ('soc_1_b3_002', '社会', 1, '北アメリカ州', 1, '北アメリカ大陸の東部を南北に連なる、低くなだらかな山脈を何というか。', 'アパラチア山脈', array['ロッキー山脈', 'アンデス山脈', 'ウラル山脈'], '東部のアパラチア山脈は標高1000m程度の低くなだらかな山脈で、周辺では石炭が産出される。西部のロッキー山脈は高くけわしい。', null),
  ('soc_1_b3_003', '社会', 1, '北アメリカ州', 1, '北アメリカ大陸の中央平原を流れ、メキシコ湾に注ぐ北アメリカ最長の川を何というか。', 'ミシシッピ川', array['アマゾン川', 'セントローレンス川', 'コロラド川'], 'ミシシッピ川は中央平原を南へ流れてメキシコ湾に注ぎ、五大湖とともに重要な内陸水路になっている。アマゾン川は南アメリカ大陸の川。', null),
  ('soc_1_b3_004', '社会', 1, '北アメリカ州', 2, 'ロッキー山脈の東側に広がる、降水量の少ない乾燥した大平原を何というか。', 'グレートプレーンズ', array['プレーリー', '中央平原', 'パンパ'], 'グレートプレーンズはロッキー山脈と西経100度の間に広がる乾燥した大平原。プレーリーは西経100度より東に広がる大草原である。', null),
  ('soc_1_b3_005', '社会', 1, '北アメリカ州', 2, 'アメリカ合衆国の西経100度より東に広がり、肥えた土壌で農業がさかんな大草原を何というか。', 'プレーリー', array['グレートプレーンズ', 'セルバ', 'サバナ'], 'プレーリーは西経100度より東の大草原で、小麦やとうもろこしの栽培がさかん。西経100度より西の乾燥した大平原はグレートプレーンズ。', null),
  ('soc_1_b3_006', '社会', 1, '北アメリカ州', 1, 'カリブ海などで発生し、メキシコ湾岸や大西洋沿岸に強風や大雨の被害をもたらす熱帯低気圧を何というか。', 'ハリケーン', array['台風', 'サイクロン', 'モンスーン'], '北アメリカをおそう熱帯低気圧はハリケーンと呼ばれる。台風は太平洋西部、サイクロンはインド洋などで発生する熱帯低気圧の呼び名である。', null),
  ('soc_1_b3_007', '社会', 1, '北アメリカ州', 1, 'カナダで英語とともに公用語となっている言語は何か。', 'フランス語', array['スペイン語', 'ポルトガル語', 'ドイツ語'], 'カナダは最初にフランス人が移住し、その後イギリス人が増えた歴史から、英語とフランス語の両方が公用語になっている。', null),
  ('soc_1_b3_008', '社会', 1, '北アメリカ州', 2, 'メキシコや西インド諸島の国々で、スペイン語が広く使われている理由として正しいものはどれか。', 'かつてスペインの植民地だったから', array['スペインとの貿易がさかんだったから', 'スペインからの観光客が多いから', 'スペインと同じ州に属しているから'], 'メキシコや西インド諸島の多くはかつてスペインの植民地だったため、現在もスペイン語が使われ、キリスト教が信仰されている。', null),
  ('soc_1_b3_009', '社会', 1, '北アメリカ州', 1, 'アメリカ合衆国の首都はどこか。', 'ワシントンD.C.', array['ニューヨーク', 'ロサンゼルス', 'シカゴ'], '首都は東部にあるワシントンD.C.。最も人口が多く自由の女神像がある都市はニューヨークで、首都ではない点に注意する。', null),
  ('soc_1_b3_010', '社会', 1, '北アメリカ州', 2, 'アメリカ合衆国・カナダ・メキシコの3か国が結び、2020年に発効した貿易協定の略称はどれか。', 'USMCA', array['ASEAN', 'APEC', 'MERCOSUR'], '北米自由貿易協定（NAFTA）に代わり、2020年にアメリカ・メキシコ・カナダ協定（USMCA）が発効した。ASEANは東南アジアの組織。', null),
  ('soc_1_b3_011', '社会', 1, '北アメリカ州', 1, 'ヨーロッパからの移民が来る前から北アメリカに住んでいた先住民を何というか。', 'ネイティブアメリカン', array['メスチーソ', 'アボリジニ', 'マオリ'], '北アメリカの先住民はネイティブアメリカンと呼ばれる。17世紀以降、ヨーロッパ系の移民が先住民の土地をうばいながら開拓を進めた。', null),
  ('soc_1_b3_012', '社会', 1, '北アメリカ州', 2, 'アメリカ合衆国で近年増えている、メキシコや中央アメリカなどから移住してきたスペイン語を話す人々を何というか。', 'ヒスパニック', array['ネイティブアメリカン', 'メスチーソ', 'イヌイット'], 'ヒスパニックは働く機会と高い賃金を求めてアメリカに移住してくる人々。ネイティブアメリカンは北アメリカの先住民を指す。', null),
  ('soc_1_b3_013', '社会', 1, '北アメリカ州', 3, 'アメリカ合衆国の南部にアフリカ系の人々が多く住んでいる歴史的な理由として正しいものはどれか。', '綿花農場で働く奴隷として連れてこられたから', array['金の採掘のために移住してきたから', '鉄道の建設のために移住してきたから', '漁業を行うために移住してきたから'], 'アフリカ大陸からは南部の綿花農場で働かせるための奴隷として多くの人々が連れてこられた。その歴史から現在も南部にアフリカ系の人々が多い。', null),
  ('soc_1_b3_014', '社会', 1, '北アメリカ州', 1, 'アメリカ合衆国の農業で、各地域の気温や降水量、土壌などの自然環境に適した農作物を栽培することを何というか。', '適地適作', array['二毛作', '促成栽培', '輪作'], 'アメリカでは各地域の自然環境に適した農作物を生産する適地適作が行われており、農業の地域区分がはっきりしている。', null),
  ('soc_1_b3_015', '社会', 1, '北アメリカ州', 2, 'アメリカ合衆国の降水量が少ない地域で行われている、くみ上げた地下水を回転するアームで円形に散水するかんがい方式を何というか。', 'センターピボット', array['フィードロット', 'プランテーション', 'サンベルト'], 'センターピボットは乾燥地域で小麦やとうもろこしの栽培を可能にするかんがい方式。フィードロットは肉牛を育てる大規模な肥育場である。', null),
  ('soc_1_b3_016', '社会', 1, '北アメリカ州', 2, 'アメリカ合衆国の西経100度より西の降水量が少ない地域で、主に行われている農牧業はどれか。', '肉牛の放牧', array['酪農', '綿花の栽培', '稲作'], '西経100度より西は年間降水量がおよそ500mmより少ない乾燥地帯で、牧草地での肉牛の放牧が中心となる。酪農は五大湖周辺でさかん。', null),
  ('soc_1_b3_017', '社会', 1, '北アメリカ州', 2, 'アメリカ合衆国の農業の特色として正しいものはどれか。', '大型機械を使い、広い農地を少ない労働力で経営している', array['小さな農地に多くの労働力を集めて経営している', '自給用の作物を中心に家族で消費する分だけ栽培している', '同じ耕地で1年に2回、同じ作物を栽培している'], 'アメリカでは1人あたりの農地面積が広く、大型機械を使って少ない労働力で経営する企業的な農業が行われ、世界最大の農産物輸出国となっている。', null),
  ('soc_1_b3_018', '社会', 1, '北アメリカ州', 2, '五大湖沿岸にあり、自動車工業の中心地として発展した都市はどこか。', 'デトロイト', array['ピッツバーグ', 'ニューヨーク', 'シアトル'], '五大湖周辺では鉄鉱石と石炭を生かしてピッツバーグで鉄鋼業が発達し、その鉄鋼を利用してデトロイトで自動車工業が発達した。', null),
  ('soc_1_b3_019', '社会', 1, '北アメリカ州', 2, 'アメリカ合衆国の北緯37度以南に広がる、先端技術産業が発達した温暖な工業地域を何というか。', 'サンベルト', array['シリコンバレー', '五大湖沿岸', 'メガロポリス'], 'サンベルトは土地が安く労働力が豊富なことから1970年代以降に工業が発達した地域。シリコンバレーはその中にあるICT産業の集中地区。', null),
  ('soc_1_b3_020', '社会', 1, '北アメリカ州', 2, 'サンフランシスコ郊外にある、ICT関連の企業や研究機関が集中している地区を何というか。', 'シリコンバレー', array['サンベルト', 'ウォール街', 'ハリウッド'], 'シリコンバレーには大学や研究機関、ICT関連企業が集中し、世界中から高度な技術をもつ人材が集まっている。', null),
  ('soc_1_b3_021', '社会', 1, '南アメリカ州', 1, '南アメリカ大陸の太平洋側を南北に連なる、高くけわしい山脈を何というか。', 'アンデス山脈', array['ロッキー山脈', 'アパラチア山脈', 'アルプス山脈'], 'アンデス山脈は南アメリカ大陸の西側（太平洋側）を南北に連なる山脈で、環太平洋造山帯の一部。ロッキー山脈は北アメリカ大陸の山脈。', null),
  ('soc_1_b3_022', '社会', 1, '南アメリカ州', 1, '赤道付近の南アメリカ大陸を流れる、流域面積が世界最大の川を何というか。', 'アマゾン川', array['ナイル川', 'ミシシッピ川', 'ラプラタ川'], 'アマゾン川は流域面積が世界最大の川で、流域には熱帯雨林が広がる。ナイル川は世界最長の川でアフリカ大陸を流れる。', null),
  ('soc_1_b3_023', '社会', 1, '南アメリカ州', 2, 'アマゾン川流域に広がる熱帯雨林を何というか。', 'セルバ', array['パンパ', 'サバナ', 'タイガ'], 'アマゾン川流域の熱帯雨林はセルバと呼ばれる。パンパはアルゼンチンの温帯草原、タイガは冷帯に広がる針葉樹林である。', null),
  ('soc_1_b3_024', '社会', 1, '南アメリカ州', 2, 'アルゼンチンのラプラタ川流域に広がり、小麦の栽培や牧畜がさかんな温帯の草原を何というか。', 'パンパ', array['セルバ', 'プレーリー', 'ステップ'], 'パンパはラプラタ川流域に広がる温帯草原で、小麦の栽培や牛の放牧がさかん。プレーリーは北アメリカの草原である。', null),
  ('soc_1_b3_025', '社会', 1, '南アメリカ州', 2, 'アンデス山脈の標高の高い地域に見られる、低緯度でも気温が低く、1年を通じて気温差が小さい気候を何というか。', '高山気候', array['地中海性気候', '温暖湿潤気候', 'ツンドラ気候'], '標高が高い地域では低緯度でも気温が低くなり、年間の気温差が小さい高山気候となる。アンデスの高地ではリャマやアルパカが飼われている。', null),
  ('soc_1_b3_026', '社会', 1, '南アメリカ州', 2, 'マチュピチュの遺跡で知られ、アンデス山脈の地域に栄えたが16世紀にスペインに滅ぼされた帝国を何というか。', 'インカ帝国', array['アステカ王国', 'マヤ文明', 'オスマン帝国'], 'インカ帝国は現在のペルーを中心に栄えた帝国で、スペインに滅ぼされた。マチュピチュはその代表的な遺跡である。', null),
  ('soc_1_b3_027', '社会', 1, '南アメリカ州', 1, 'ブラジルで公用語となっている言語は何か。', 'ポルトガル語', array['スペイン語', '英語', 'フランス語'], 'ブラジルはかつてポルトガルの植民地だったためポルトガル語が公用語。南アメリカの他の多くの国ではスペイン語が使われている。', null),
  ('soc_1_b3_028', '社会', 1, '南アメリカ州', 1, '植民地時代の影響で、南アメリカの多くの国で信仰されている宗教は何か。', 'キリスト教', array['イスラム教', 'ヒンドゥー教', '仏教'], '南アメリカの多くの国はスペインやポルトガルの植民地だった影響で、キリスト教を信仰する人が多い。', null),
  ('soc_1_b3_029', '社会', 1, '南アメリカ州', 2, '南アメリカで、先住民と白人との間の混血の人々を何というか。', 'メスチーソ', array['インディオ', 'ヒスパニック', 'アボリジニ'], 'メスチーソは先住民と白人との混血の人々。南アメリカの先住民はインディオと呼ばれる。', null),
  ('soc_1_b3_030', '社会', 1, '南アメリカ州', 1, '森林を焼きはらい、その灰を肥料としていもやとうもろこしなどを栽培する農業を何というか。', '焼畑農業', array['混合農業', '酪農', '遊牧'], '焼畑農業は森林を焼いた灰を肥料として利用する農業で、アマゾン川流域などで伝統的に行われてきた。', null),
  ('soc_1_b3_031', '社会', 1, '南アメリカ州', 2, 'ブラジル高原でプランテーションによる栽培が広まり、かつてブラジルの輸出の中心だった農作物は何か。', 'コーヒー豆', array['カカオ豆', '茶', '天然ゴム'], 'ブラジルではコーヒー豆の栽培がさかんで、かつてはコーヒー豆の輸出に頼るモノカルチャー経済だった。カカオ豆はアフリカのギニア湾岸が主産地。', null),
  ('soc_1_b3_032', '社会', 1, '南アメリカ州', 2, 'チリで産出量が多く、重要な輸出品となっている鉱産資源は何か。', '銅', array['鉄鉱石', '石油', 'ボーキサイト'], 'チリは世界有数の銅の産出国である。鉄鉱石はブラジル、石油はベネズエラなどで産出が多い。', null),
  ('soc_1_b3_033', '社会', 1, '南アメリカ州', 2, 'ブラジルで産出量が多く、日本へも輸出されている鉱産資源は何か。', '鉄鉱石', array['銅', 'すず', '石炭'], 'ブラジルは世界有数の鉄鉱石の産出国で、日本にも多く輸出している。銅はチリでの産出が多い。', null),
  ('soc_1_b3_034', '社会', 1, '南アメリカ州', 2, 'ブラジルで自動車の燃料などに使われている、さとうきびなどの植物を原料とする燃料を何というか。', 'バイオエタノール', array['シェールガス', '液化天然ガス', 'コークス'], 'バイオエタノール（バイオ燃料）はさとうきびなどを原料とする再生可能エネルギー。一方で、畑を広げるための熱帯林の伐採が問題になっている。', null),
  ('soc_1_b3_035', '社会', 1, '南アメリカ州', 2, 'アマゾン川流域で、農地や道路の開発が進むことによって起こっている環境問題はどれか。', '熱帯林の減少', array['砂漠化の進行', '酸性雨の被害', 'オゾン層の破壊'], '農地や道路の開発により熱帯林の減少が進み、地球温暖化への影響が心配されている。開発と環境保全を両立する持続可能な開発が課題である。', null),
  ('soc_1_b3_036', '社会', 1, 'アフリカ州', 1, 'アフリカ大陸の北部に広がる、世界最大の砂漠を何というか。', 'サハラ砂漠', array['ゴビ砂漠', 'カラハリ砂漠', 'グレートビクトリア砂漠'], 'サハラ砂漠はアフリカ大陸北部に広がる世界最大の砂漠。ゴビ砂漠はアジア、グレートビクトリア砂漠はオーストラリアにある。', null),
  ('soc_1_b3_037', '社会', 1, 'アフリカ州', 1, 'エジプトを流れて地中海に注ぐ、世界最長の川を何というか。', 'ナイル川', array['アマゾン川', 'コンゴ川', 'ニジェール川'], 'ナイル川は世界最長の川で、エジプトの農業はナイル川の水に支えられてきた。流域面積が世界最大なのはアマゾン川である。', null),
  ('soc_1_b3_038', '社会', 1, 'アフリカ州', 2, 'サハラ砂漠の南に接し、砂漠化の進行が問題となっている地域を何というか。', 'サヘル', array['サバナ', 'ステップ', 'パンパ'], 'サヘルはサハラ砂漠の南縁の地域で、過放牧やたきぎの取りすぎ、気候の変化などにより砂漠化が進んでいる。', null),
  ('soc_1_b3_039', '社会', 1, 'アフリカ州', 3, '緯度0度の赤道と経度0度の本初子午線が交わる地点に最も近い、アフリカ大陸沿岸の湾はどこか。', 'ギニア湾', array['メキシコ湾', 'ペルシャ湾', 'ベンガル湾'], '赤道と本初子午線はアフリカ大陸の西側にあるギニア湾上で交わる。地図上の位置を問う問題でよく出題される。', null),
  ('soc_1_b3_040', '社会', 1, 'アフリカ州', 2, 'アフリカに直線的な国境線が多い理由として正しいものはどれか。', '植民地時代に緯線や経線を利用して境界が引かれたから', array['山脈や川などの自然の地形に沿って境界が引かれたから', '民族のまとまりに合わせて境界が引かれたから', '住民の投票によって境界が決められたから'], '植民地時代にヨーロッパ諸国が緯線や経線を利用して境界を引いたため、直線的な国境線が多い。民族の分布を無視した国境は紛争の原因にもなった。', null),
  ('soc_1_b3_041', '社会', 1, 'アフリカ州', 2, '南アフリカ共和国でかつて行われていた、人種によって人々を差別し隔離する政策を何というか。', 'アパルトヘイト', array['白豪主義', 'モノカルチャー', 'プランテーション'], 'アパルトヘイトは南アフリカ共和国でかつて行われていた人種隔離政策で、現在は廃止されている。白豪主義はオーストラリアの移民制限政策。', null),
  ('soc_1_b3_042', '社会', 1, 'アフリカ州', 1, 'コートジボワールやガーナなどギニア湾岸の国々で栽培がさかんな、チョコレートの原料となる農作物は何か。', 'カカオ豆', array['コーヒー豆', '茶', 'さとうきび'], 'ギニア湾岸の国々ではプランテーションでのカカオ豆の栽培がさかん。茶はケニア、コーヒー豆はエチオピアなどで栽培が多い。', null),
  ('soc_1_b3_043', '社会', 1, 'アフリカ州', 2, '埋蔵量が少なく取り出すのが難しい金属の総称で、スマートフォンなどの電子機器に使われ、アフリカ南部などで産出されるものを何というか。', 'レアメタル', array['ボーキサイト', 'アルミニウム', 'ウラン'], 'レアメタル（希少金属）は電子機器の生産に欠かせない金属の総称で、南アフリカ共和国などアフリカ南部で多く産出される。', null),
  ('soc_1_b3_044', '社会', 1, 'アフリカ州', 2, 'アフリカの多くの国で見られる、特定の農産物や鉱産資源の輸出にたよる経済を何というか。', 'モノカルチャー経済', array['フェアトレード', 'プランテーション', '持続可能な開発'], 'モノカルチャー経済は輸出品の価格変動の影響を受けやすく、国の収入が不安定になりやすい。フェアトレードは途上国の産品を適正な価格で取引するしくみ。', null),
  ('soc_1_b3_045', '社会', 1, 'アフリカ州', 2, '発展途上国の農産物などを適正な価格で取引し、生産者の生活を支えるしくみを何というか。', 'フェアトレード', array['モノカルチャー経済', 'プランテーション', 'ODA'], 'フェアトレード（公正貿易）は発展途上国の産品を適正な価格で取引するしくみ。ODAは先進国の政府が行う政府開発援助のこと。', null),
  ('soc_1_b3_046', '社会', 1, 'オセアニア州', 1, 'オーストラリアの先住民を何というか。', 'アボリジニ', array['マオリ', 'イヌイット', 'インディオ'], 'オーストラリアの先住民はアボリジニ。マオリはニュージーランドの先住民である。', null),
  ('soc_1_b3_047', '社会', 1, 'オセアニア州', 2, 'ニュージーランドの先住民を何というか。', 'マオリ', array['アボリジニ', 'メスチーソ', 'ネイティブアメリカン'], 'ニュージーランドの先住民はマオリで、その文化を尊重する取り組みが進められている。アボリジニはオーストラリアの先住民。', null),
  ('soc_1_b3_048', '社会', 1, 'オセアニア州', 2, 'オーストラリアでかつてとられていた、ヨーロッパ系以外の移民を制限する政策を何というか。', '白豪主義', array['アパルトヘイト', '多文化主義', '保護貿易'], '白豪主義はヨーロッパ系以外の移民を制限する政策だったが撤廃され、現在は多文化社会をめざしている。アパルトヘイトは南アフリカ共和国の政策。', null),
  ('soc_1_b3_049', '社会', 1, 'オセアニア州', 2, 'オーストラリアの首都はどこか。', 'キャンベラ', array['シドニー', 'メルボルン', 'ウェリントン'], 'オーストラリアの首都はキャンベラ。最大の都市シドニーと間違えやすいので注意する。ウェリントンはニュージーランドの首都。', null),
  ('soc_1_b3_050', '社会', 1, 'オセアニア州', 2, 'オーストラリア大陸の国土の大部分を占める気候帯はどれか。', '乾燥帯', array['熱帯', '温帯', '冷帯'], 'オーストラリアは国土の大部分が乾燥帯で、人口は温帯の東部や南西部の沿岸に集中している。北部には熱帯が分布する。', null)
